import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Drawer from "../../ui/shadcn-drawer";

// MODEL

export const Model = S.Struct({
  open: S.Boolean,
});

export type Model = typeof Model.Type;

// MESSAGE

export const ClickedOpenDrawer = m("ClickedOpenDrawer");
export const ClickedCancel = m("ClickedCancel");
export const ClickedSubmit = m("ClickedSubmit");

export const Message = S.Union([
  ClickedOpenDrawer,
  ClickedCancel,
  ClickedSubmit,
]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ open: false }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedOpenDrawer: () => [evo(model, { open: () => true }), []],
      ClickedCancel: () => [evo(model, { open: () => false }), []],
      ClickedSubmit: () => [evo(model, { open: () => false }), []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();
  const titleId = "drawer-rtl-title";
  const descriptionId = "drawer-rtl-description";

  return h.div(
    [h.Attribute("dir", "rtl"), h.Class("flex flex-wrap gap-2 text-right")],
    [
      Drawer.rootView<Message>({
        children: [
          Drawer.triggerView<Message>({
            onClick: ClickedOpenDrawer(),
            children: [h.span([], ["فتح الدرج"])],
          }),
          Drawer.portalView<Message>({
            open: model.open,
            children: [
              Drawer.backdropView<Message>({ children: [] }),
              Drawer.viewportView<Message>({
                children: [
                  Drawer.popupView<Message>({
                    titleId,
                    descriptionId,
                    children: [
                      Drawer.contentView<Message>({
                        children: [
                          Drawer.titleView<Message>({
                            id: titleId,
                            children: [h.span([], ["نقل الهدف"])],
                          }),
                          Drawer.descriptionView<Message>({
                            id: descriptionId,
                            children: [h.span([], ["حدد هدف نشاطك اليومي."])],
                          }),
                        ],
                      }),
                      h.div(
                        [h.Class("mt-auto grid gap-2")],
                        [
                          h.button(
                            [
                              h.Type("button"),
                              h.OnClick(ClickedSubmit()),
                              h.Class(Drawer.shadcnDrawerTriggerClassName),
                            ],
                            ["إرسال"]
                          ),
                          Drawer.closeView<Message>({
                            onClick: ClickedCancel(),
                            children: [h.span([], ["إلغاء"])],
                          }),
                        ]
                      ),
                    ],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnDrawerRtlExample from "./main";

describe("shadcn Drawer RTL example", () => {
  test("opens and closes localized rtl drawer content", () => {
    Scene.scene(
      {
        update: ShadcnDrawerRtlExample.update,
        view: ShadcnDrawerRtlExample.view,
      },
      Scene.with(ShadcnDrawerRtlExample.init()[0]),
      Scene.click(Scene.role("button", { name: "فتح الدرج" })),
      Scene.expect(Scene.role("dialog", { name: "نقل الهدف" })).toExist(),
      Scene.expect(Scene.text("حدد هدف نشاطك اليومي.")).toExist(),
      Scene.click(Scene.role("button", { name: "إلغاء" })),
      Scene.expect(Scene.role("dialog", { name: "نقل الهدف" })).not.toExist()
    );
  });
});
